import index from '@/data/place-index.json';
import { createPortal, portalConfigFromEnv, type Catalog } from '@/server/portal';

/**
 * The hosted business-owner API: the catalog injected and the portal built once. It is injected here rather than in
 * portal.ts so that module stays plain TypeScript the tests can import without a catalog.
 *
 * The routes need only a place id and its name, so they read src/data/place-index.json (265 KB, generated by
 * scripts/build-place-index.mjs) instead of the 4.5 MB directory.json, which would go into every deployed worker.
 */
const names = index as Record<string, string | undefined>;
const catalog: Catalog = { has: (placeId) => typeof names[placeId] === 'string', name: (placeId) => names[placeId] ?? null };

// Built on first use, so it reads the deployed environment.
let handle: ReturnType<typeof createPortal> | undefined;
export const portal = () => (handle ??= createPortal(portalConfigFromEnv(process.env, catalog)));
